
const $ = id => document.getElementById(id);
const rnd = n => Math.floor(Math.random() * n);
const pick = a => a[rnd(a.length)];
const shuffle = a => [...a].sort(() => Math.random() - .5);
const F = (a, b) => `<span class="frac"><span>${a}</span><span>${b}</span></span>`;
const KIND = {choco: "🍫", pizza: "🍕", cake: "🍰", apple: "🍎", cookie: "🍪"};
const GLOSS = `<section class="card gloss"><div class="gl top"><b>NUMERADOR</b><br>(ARRIBA)<br><small>CUÁNTAS PARTES TOMAMOS</small></div><div>${F(3, 4)}</div><div class="gl bot"><b>DENOMINADOR</b><br>(ABAJO)<br><small>EN CUÁNTAS PARTES IGUALES SE DIVIDIÓ EL TODO</small></div></section>`;
const FOOD='data:image/webp;base64,';let foodUid=0;
const pizza = (n,k,clk) => {const id='food'+(++foodUid);let out='<svg viewBox="-18 -18 236 236" class="pz realpizza" aria-label="PIZZA DIVIDIDA EN '+n+' PARTES IGUALES">';for(let i=0;i<n;i++){const on=Array.isArray(k)?k[i]:i<k;const a=2*Math.PI*i/n-Math.PI/2,b=2*Math.PI*(i+1)/n-Math.PI/2,m=(a+b)/2;const d=`M100 100 L${100+95*Math.cos(a)} ${100+95*Math.sin(a)} A95 95 0 ${n===1?1:0} 1 ${100+95*Math.cos(b)} ${100+95*Math.sin(b)} Z`;out+=`<defs><clipPath id="${id}-${i}"><path d="${d}"/></clipPath></defs><g transform="translate(${on?Math.cos(m)*11:0} ${on?Math.sin(m)*11:0})" ${clk?`role="button" tabindex="0" aria-label="PORCIÓN ${i+1}" aria-pressed="${on}" onclick="tapCell(${i})" onkeydown="if(event.key==='Enter'||event.key===' '){event.preventDefault();tapCell(${i})}"`:''}><image href="${FOOD}" x="0" y="0" width="400" height="200" preserveAspectRatio="none" clip-path="url(#${id}-${i})"/><path d="${d}" fill="${on?'#facc1533':'transparent'}" stroke="${on?'#fde047':'white'}" stroke-width="${on?4:2}"/></g>`;}return out+'</svg>'};
const chocolate=(n,k,clk)=>{const uid='choco'+(++foodUid),w=600,h=240,pw=w/n;let out=`<svg class="chocolate-equal" viewBox="-6 -26 612 278" role="group" aria-label="BARRA DE CHOCOLATE DIVIDIDA EN ${n} PORCIONES IGUALES"><rect x="-5" y="-5" width="610" height="250" rx="10" fill="#f8ecd0"/>`;for(let i=0;i<n;i++){const on=Array.isArray(k)?k[i]:i<k;out+=`<defs><clipPath id="${uid}-${i}"><rect x="${i*pw}" y="0" width="${pw}" height="${h}"/></clipPath></defs><g transform="translate(0 ${on?-19:0})" ${clk?`role="button" tabindex="0" aria-label="PORCIÓN ${i+1} DE ${n}, TODAS DEL MISMO TAMAÑO" aria-pressed="${on}" onclick="tapCell(${i})" onkeydown="if(event.key==='Enter'||event.key===' '){event.preventDefault();tapCell(${i})}"`:''}><g clip-path="url(#${uid}-${i})"><svg x="0" y="0" width="600" height="240" viewBox="920 220 820 510" preserveAspectRatio="none"><image href="${FOOD}" x="0" y="0" width="1774" height="887" preserveAspectRatio="none"/></svg></g><rect x="${i*pw}" y="0" width="${pw}" height="${h}" fill="${on?'#facc1522':'transparent'}" stroke="${on?'#fde047':'#fff5dd'}" stroke-width="5"/><text x="${(i+.5)*pw}" y="223" text-anchor="middle" fill="white" stroke="#351a0c" stroke-width="3" paint-order="stroke" font-family="Arial" font-weight="900" font-size="23" pointer-events="none">${i+1}</text></g>`;}return out+'</svg><div class="equal-caption">'+n+' PORCIONES IGUALES · CADA UNA ES 1/'+n+' DEL ENTERO</div>'};
const bars=(n,k,clk)=>S.kind==='pizza'?pizza(n,k,clk):chocolate(n,k,clk);
const profe = msg => `<div class="profe"><div class="avatar"><img src="data:image/webp;base64," alt="PROFE MARTÍN: PERSONAJE CON CABELLO VERDE Y TURQUESA, GUARDAPOLVO Y LIBRO AZUL"></div><div class="bubble">${msg}</div><button class="snd" onclick="speakBubble(this)" aria-label="ESCUCHAR">🔊</button></div>`;
const clean = h => { const d = document.createElement("div"); d.innerHTML = h.replace(/<span class="frac"><span>(\d+)<\/span><span>(\d+)<\/span><\/span>/g, " $1 SOBRE $2 ").replace(/<br>/g, ". "); return d.textContent.replace(/[✔✘💡🎉·]/g, " ").replace(/\s+/g, " ").trim(); };
const speakText = t => { if (!("speechSynthesis" in window) || !t) return; speechSynthesis.cancel(); const u = new SpeechSynthesisUtterance(t); u.lang = "es-ES"; u.rate = 0.78; u.onstart = () => document.querySelector(".profe")?.classList.add("talking"); u.onend = u.onerror = () => document.querySelector(".profe")?.classList.remove("talking"); const v = speechSynthesis.getVoices().find(x => x.lang.startsWith("es")); if (v) u.voice = v; speechSynthesis.speak(u); };
const speakBubble = b => speakText(clean(b.previousElementSibling.innerHTML));
const speakFb = () => speakText($("fb") ? $("fb").textContent : "");
const burst = e => { for (let i = 0; i < 12; i++) { const el = document.createElement("div"); el.className = "burst"; el.textContent = e; el.style.left = "50%"; el.style.top = "40%"; el.style.setProperty("--dx", (Math.random() * 320 - 160) + "px"); el.style.setProperty("--dy", (Math.random() * 320 - 200) + "px"); document.body.appendChild(el); setTimeout(() => el.remove(), 1000); } };

/* ESTACIONES: cada una enseña un tema con el profe y tiene 3 desafíos */
const STA = [
  { n: "TABLETA 🍫", ic: "🍫", in: ["UNA FRACCIÓN ES UNA PARTE DE UN TODO: COMO UNA TABLETA DE CHOCOLATE DIVIDIDA EN PARTES IGUALES.", "ABAJO: EN CUÁNTAS PARTES IGUALES SE DIVIDE EL TODO.", "ARRIBA: CUÁNTAS PARTES TOMAMOS."], h: "CONTÁ EL TOTAL DE PARTES PARA SABER CUÁNTAS PINTAR." },
  { n: "LECTURA 📖", ic: "📖", in: ["PARA LEER UNA FRACCIÓN MIRÁ LA FIGURA.", "CONTÁ EL TOTAL (ABAJO) Y LAS PINTADAS (ARRIBA)."], h: "EL DE ABAJO ES EL TOTAL. EL DE ARRIBA ES LO PINTADO." },
  { n: "UNIÓN 🔗", ic: "🔗", in: ["UNIR ES CONECTAR UNA FIGURA CON SU FRACCIÓN.", "TOCÁ UNA FIGURA Y DESPUÉS SU FRACCIÓN."], h: "BUSCÁ CUÁNTAS PARTES ESTÁN PINTADAS Y CUÁNTAS HAY EN TOTAL." },
  { n: "VERDADERO O FALSO ✅", ic: "✅", in: ["A VECES LA FRACCIÓN ESCRITA NO COINCIDE CON LA FIGURA.", "REVISÁ ARRIBA Y ABAJO ANTES DE DECIDIR."], h: "COMPARÁ EL NÚMERO DE ARRIBA CON LO PINTADO Y EL DE ABAJO CON EL TOTAL." },
  { n: "ARMÁ LA FRACCIÓN 🧩", ic: "🧩", in: ["PODÉS ARMAR LA FRACCIÓN CON LOS BOTONES + Y −.", "ARRIBA: PARTES PINTADAS. ABAJO: PARTES TOTALES."], h: "USÁ + Y − HASTA QUE LA FRACCIÓN COINCIDA CON LA FIGURA." },
  { n: "EQUIVALENTES ✨", ic: "✨", in: ["DOS FRACCIONES SON IGUALES SI VALEN LO MISMO.", "MULTIPLICÁ ARRIBA Y ABAJO POR EL MISMO NÚMERO."], h: "MULTIPLICÁ ARRIBA Y ABAJO POR EL MISMO NÚMERO." }
];
const Q = [
  "SEPARÁ LAS PORCIONES QUE TE PIDO.", "ELEGÍ LA FRACCIÓN QUE MUESTRA LA FIGURA.", "UNÍ CADA FIGURA CON SU FRACCIÓN.",
  "¿ESTA FRACCIÓN COINCIDE CON LA FIGURA?", "ARMÁ LA FRACCIÓN QUE MUESTRA LA FIGURA.", "¿CUÁL FRACCIÓN VALE LO MISMO?"
];

const S = { st: -1, ch: 0, cor: 0, ans: false, comp: [false,false,false,false,false,false], stars: [0,0,0,0,0,0], done: 0, score: 0, streak: 0, d: {}, sel: null, mat: [false,false], err: false, cn: 0, cd: 1 };

function hud() {
  $("pSt").textContent = S.st < 0 ? "MAPA" : `ESTACIÓN ${S.st + 1} DE 6`;
  $("pSc").textContent = `PUNTOS: ${S.score}`;
  $("pSe").textContent = `SEGUIDOS: ${S.streak}`;
  $("bar").style.width = (S.done / 6 * 100) + "%";
}
function say(cls, msg) { const f = $("fb"); if (f) { f.className = "feed " + cls; f.textContent = msg; } }

function renderMap() { S.lab=false;
  S.st = -1; hud();
  const tiles = STA.map((s, i) => {
    const locked = i > 0 && !S.comp[i - 1];
    return `<button class="tile" ${locked ? "disabled" : ""} onclick="startStation(${i})"><div class="ti">${locked ? "🔒" : s.ic}</div>${s.n}<div class="st">${S.comp[i] ? "⭐".repeat(S.stars[i]) : locked ? "" : "JUGAR ▶"}</div></button>`;
  }).join("");
  $("app").innerHTML = profe(S.done === 0 ? "¡HOLA! SOY EL PROFE MARTÍN. ELEGÍ UNA ESTACIÓN Y VAMOS A APRENDER JUGANDO." : "¡MUY BIEN! ELEGÍ LA PRÓXIMA ESTACIÓN.") + `<section class="card"><h2>MAPA DE LA MISIÓN</h2><button class="btn" onclick="openLab()">🍕 EXPLORAR CON ALIMENTOS REALES</button><div class="map">${tiles}</div></section>`;
}

function startStation(i) { S.lab=false;
  S.st = i; S.ch = 0; S.cor = 0; hud();
  const s = STA[i];
  $("app").innerHTML = profe(`<b>${s.n}</b><br><br>${s.in.join("<br>")}`) + GLOSS + `<section class="card center"><button class="btn" onclick="newChallenge()">EMPEZAR ▶</button><button class="btn ghost" onclick="renderMap()">VOLVER</button></section>`;
}

function newChallenge() {
  S.ans = false; S.sel = null; S.mat = [false, false]; S.err = false; S.kind = pick(["choco", "pizza"]);
  const t = S.st;
  if (t === 0) { const n = pick([2,3,4,5,6,8]); S.d = { n, k: 1 + rnd(n - 1), cells: Array(n).fill(false) }; }
  if (t === 1) { const n = pick([2,3,4,5,6,8]), k = 1 + rnd(n - 1); S.d = { n, k, good: [k, n], opts: shuffle([[k,n],[k,n+1],[n,k]]) }; }
  if (t === 2) {
    let p; do { p = [0,1].map(() => { const n = pick([2,3,4,5,6,8]); return { n, k: 1 + rnd(n - 1) }; }); } while (p[0].k * p[1].n === p[1].k * p[0].n);
    S.d = { p, ro: shuffle([0,1]) };
  }
  if (t === 3) { const n = pick([2,3,4,5,6,8]), k = 1 + rnd(n - 1), truth = rnd(2) === 0; const claim = truth ? [k,n] : pick([[k,n+1],[n,k]]); S.d = { n, k, claim, truth }; }
  if (t === 4) { const n = pick([2,3,4,5,6,8]); S.d = { n, k: 1 + rnd(n - 1) }; S.cn = 0; S.cd = 1; }
  if (t === 5) { const b = pick([[1,2],[1,3],[2,3],[1,4],[3,4]]), f = pick([2,3]); const good = [b[0]*f, b[1]*f]; S.d = { base: b, f, good, opts: shuffle([good, [good[0]+1, good[1]], [good[0], good[1]+1]]) }; }
  renderChallenge();
}

function renderChallenge() {
  hud();
  const d = S.d, t = S.st;
  let body = "";
  if (t === 0) body = `<p class="big">SEPARÁ ${d.k} DE ${d.n} PARTES.</p>${bars(d.n, d.cells, true)}${liveCount()}<div class="center"><button class="btn" onclick="check0()" ${S.ans ? "disabled" : ""}>¡LISTO! ✔</button></div>`;
  if (t === 1) body = `<p class="big">¿QUÉ FRACCIÓN MUESTRA LA FIGURA?</p>${bars(d.n, d.k, false)}<div class="opts">${d.opts.map((o,i) => `<button class="opt" onclick="pickOpt(${i})">${F(o[0],o[1])}</button>`).join("")}</div>`;
  if (t === 2) body = `<p class="big">TOCÁ UNA FIGURA Y DESPUÉS SU FRACCIÓN.</p><div class="pairs"><div>${d.p.map((p,i) => `<button class="side ${S.mat[i] ? "ok" : S.sel === i ? "sel" : ""}" onclick="tapL(${i})">${bars(p.n, p.k, false)}</button>`).join("")}</div><div>${d.ro.map((j,r) => `<button class="opt ${S.mat[j] ? "ok" : ""}" ${S.mat[j] ? "disabled" : ""} onclick="tapR(${r})">${F(d.p[j].k, d.p[j].n)}</button>`).join("")}</div></div>`;
  if (t === 3) body = `<p class="big">LA FIGURA MUESTRA ${d.k} DE ${d.n} PARTES.<br>¿ES ESTA FRACCIÓN?</p><div class="center">${F(d.claim[0], d.claim[1])}</div>${bars(d.n, d.k, false)}<div class="opts"><button class="opt" onclick="pickVF(true)">VERDADERO ✔</button><button class="opt" onclick="pickVF(false)">FALSO ✘</button></div>`;
  if (t === 4) body = `<p class="big">${Q[4]}</p>${bars(d.n, d.k, false)}<div class="adj"><span>ARRIBA</span><button class="pm" onclick="adj(0,-1)">−</button><span class="num">${S.cn}</span><button class="pm" onclick="adj(0,1)">+</button></div><div class="adj"><span>ABAJO</span><button class="pm" onclick="adj(1,-1)">−</button><span class="num">${S.cd}</span><button class="pm" onclick="adj(1,1)">+</button></div><div class="center">${F(S.cn, S.cd)}<br><button class="btn" onclick="check4()" ${S.ans ? "disabled" : ""}>¡LISTO! ✔</button></div>`;
  if (t === 5) body = `<p class="big">LA FIGURA MUESTRA ${F(d.base[0], d.base[1])}.<br>${Q[5]}</p>${bars(d.base[1], d.base[0], false)}<div class="opts">${d.opts.map((o,i) => `<button class="opt" onclick="pickOpt(${i})">${F(o[0],o[1])}</button>`).join("")}</div>`;
  $("app").innerHTML = profe(Q[t]) + (t===0?foodControls():'') + `<section class="card"><h2>${STA[t].n} · DESAFÍO ${S.ch + 1} DE 3</h2><div class="legend"><b>NUMERADOR</b> (ARRIBA) = LO QUE TOMAMOS · <b>DENOMINADOR</b> (ABAJO) = TOTAL DE PARTES IGUALES</div>${body}<div class="feed" id="fb"></div><div id="nav"></div><button class="btn ghost" onclick="hint()">💡 PISTA</button></section>`;
}

function tapCell(i) {if(S.lab){S.d.cells[i]=!S.d.cells[i];renderLab();return}if(S.ans)return;S.d.cells[i]=!S.d.cells[i];renderChallenge();}

function check0() { const p = S.d.cells.filter(Boolean).length; fin(p === S.d.k, p === S.d.k ? `¡MUY BIEN! SEPARASTE ${S.d.k} DE ${S.d.n}.` : `SEPARASTE ${p}. NECESITABAS ${S.d.k}. EL DE ABAJO ES EL TOTAL.`); }
function pickOpt(i) {
  if (S.ans) return;
  const o = S.d.opts[i], g = S.d.good, ok = o[0] === g[0] && o[1] === g[1];
  document.querySelectorAll(".opt").forEach((b, j) => { const oj = S.d.opts[j]; if (oj[0] === g[0] && oj[1] === g[1]) b.classList.add("ok"); else if (j === i) b.classList.add("bad"); });
  fin(ok, ok ? "¡BIEN! ESA ES LA FRACCIÓN." : `LA CORRECTA ERA ${g[0]} DE ${g[1]}.`);
}
function tapL(i) { if (S.ans || S.mat[i]) return; S.sel = i; renderChallenge(); }
function tapR(r) {
  if (S.ans || S.sel === null) return;
  const j = S.d.ro[r];
  if (S.sel === j) { S.mat[j] = true; S.sel = null; if (S.mat[0] && S.mat[1]) return fin(!S.err, S.err ? "¡LAS UNISTE! AHORA SABÉS MEJOR LAS FRACCIONES." : "¡PERFECTO! UNISTE LAS DOS."); renderChallenge(); say("ok", "¡SÍ! ESA ES. SEGUÍ."); }
  else { S.err = true; S.sel = null; renderChallenge(); say("bad", "NO ES ESA. PROBÁ OTRA VEZ."); }
}
function pickVF(v) { fin(v === S.d.truth, v === S.d.truth ? "¡CORRECTO!" : (S.d.truth ? "ERA VERDADERO: LA FRACCIÓN SÍ COINCIDE CON LA FIGURA." : `ERA FALSO: LA FIGURA MUESTRA ${S.d.k} DE ${S.d.n}.`)); }
function adj(w, dl) { if (S.ans) return; if (w === 0) S.cn = Math.max(0, Math.min(8, S.cn + dl)); else S.cd = Math.max(1, Math.min(8, S.cd + dl)); renderChallenge(); }
function check4() { const ok = S.cn === S.d.k && S.cd === S.d.n; fin(ok, ok ? "¡ARMASTE LA FRACCIÓN!" : `LA FRACCIÓN ERA ${S.d.k} DE ${S.d.n}.`); }
function hint() { say("", "💡 " + STA[S.st].h); }

function fin(ok, msg) {
  if (S.ans) return;
  S.ans = true;
  if (ok) { S.cor++; S.score += 10 + S.streak * 2; S.streak++; burst("🎉"); } else S.streak = 0;
  hud();
  say(ok ? "ok" : "bad", (ok ? "✔ " : "✘ ") + msg);
  $("nav").innerHTML = `<button class="btn" onclick="nextCh()">SIGUIENTE ▶</button> <button class="btn ghost" onclick="speakFb()">🔊 ESCUCHAR</button>`;
}
function nextCh() { S.ch++; if (S.ch >= 3) return stationEnd(); newChallenge(); }
function stationEnd() {
  const st = S.cor >= 3 ? 3 : S.cor >= 2 ? 2 : 1;
  S.stars[S.st] = Math.max(S.stars[S.st], st);
  S.comp[S.st] = true;
  S.done = S.comp.filter(Boolean).length;
  hud();
  const last = S.done === 6;
  $("app").innerHTML = profe(`¡ESTACIÓN TERMINADA! ACERTASTE ${S.cor} DE 3.`) + `<section class="card center"><div class="stars">${"⭐".repeat(st)}${"☆".repeat(3 - st)}</div><div class="small">RECORDÁ: ARRIBA ES LO PINTADO, ABAJO ES EL TOTAL.</div><button class="btn" onclick="${last ? "endScreen()" : "renderMap()"}">${last ? "VER TROFEO 🏆" : "VOLVER AL MAPA 🗺"}</button></section>`;
}
function endScreen() {
  hud();
  const total = S.stars.reduce((a, b) => a + b, 0);
  $("app").innerHTML = profe("¡GANASTE! SABÉS QUÉ ES UNA FRACCIÓN Y CÓMO SE USA.") + `<section class="card center"><h2>🏆 CAMPEÓN DE FRACCIONES 🏆</h2><div class="stars">${"⭐".repeat(total > 12 ? 3 : 1)}</div><div class="big">PUNTOS: ${S.score}</div><div class="small">ARRIBA: CUÁNTAS PARTES TOMAMOS. ABAJO: EN CUÁNTAS PARTES IGUALES SE DIVIDIÓ EL TODO.</div><button class="btn" onclick="reset()">JUGAR DE NUEVO 🔄</button></section>`;
  $("bar").style.width = "100%";
}
function reset() { Object.assign(S, { st: -1, ch: 0, cor: 0, comp: [false,false,false,false,false,false], stars: [0,0,0,0,0,0], done: 0, score: 0, streak: 0 }); renderMap(); }


function foodControls(){return `<div class="foodpick"><button class="${S.kind==='pizza'?'active':''}" onclick="setFood('pizza')">🍕 PIZZA</button><button class="${S.kind==='choco'?'active':''}" onclick="setFood('choco')">🍫 CHOCOLATE</button></div>`}
function setFood(k){S.kind=k;S.lab?renderLab():renderChallenge()}
function liveCount(){const c=S.d.cells.filter(Boolean).length;return `<div class="counter" aria-live="polite">SEPARASTE ${c} DE ${S.d.n} PARTES IGUALES: ${F(c,S.d.n)}<div class="small">TOCÁ UNA PARTE PARA SEPARARLA. TOCALA OTRA VEZ PARA DEVOLVERLA.</div></div>`}
function openLab(){S.lab=true;S.st=-1;S.kind='pizza';S.d={n:4,cells:Array(4).fill(false)};renderLab()}
function labParts(n){S.d={n:Number(n),cells:Array(Number(n)).fill(false)};renderLab()}
function renderLab(){hud();$('app').innerHTML=profe('¡VAMOS A EXPERIMENTAR! ELEGÍ UN ALIMENTO Y EN CUÁNTAS PARTES IGUALES QUERÉS DIVIDIRLO. TOCÁ LAS PORCIONES PARA SEPARARLAS.')+`<section class="card"><h2>LABORATORIO DE FRACCIONES</h2>${foodControls()}<div class="foodpick"><label>PARTES IGUALES <select aria-label="CANTIDAD DE PARTES IGUALES" onchange="labParts(this.value)">${[2,3,4,5,6,8].map(n=>`<option ${n===S.d.n?'selected':''}>${n}</option>`).join('')}</select></label></div>${bars(S.d.n,S.d.cells,true)}${liveCount()}<div class="center"><button class="btn" onclick="explainLab()">🔊 EXPLICAME LO QUE HICE</button><button class="btn ghost" onclick="labParts(S.d.n)">JUNTAR TODO</button><button class="btn ghost" onclick="renderMap()">VOLVER AL MAPA</button></div></section>`}
function explainLab(){const c=S.d.cells.filter(Boolean).length;speakText(`Dividiste el entero en ${S.d.n} partes iguales. Separaste ${c}. Tu fracción es ${c} sobre ${S.d.n}. El numerador es ${c}, porque son las partes que separaste. El denominador es ${S.d.n}, porque es el total de partes iguales.`)}
renderMap();


/* DOCENTE INTERACTIVO: REACCIONES Y AYUDA SEGÚN CADA ACCIÓN */
let profVoice=true,profLast='',profTicket=0,profGoal=null;
const profStyle=document.createElement('style');profStyle.textContent=`.profe{position:relative}.profe .avatar{cursor:pointer}.profe .bubble{min-width:0}.prof-tools{display:flex;flex-wrap:wrap;gap:7px;margin-top:10px}.prof-tools button{font:inherit;font-size:.75rem;font-weight:900;border:2px solid #9b69d8;color:#39205f;background:#f5eaff;border-radius:10px;padding:9px;min-height:40px;cursor:pointer}.prof-emotion{position:absolute;top:4px;left:7px;font-size:25px;pointer-events:none}.profe[data-mood=happy] .avatar{animation:profJump .6s ease 2}.profe[data-mood=think] .avatar{transform:rotate(-4deg)}.profe.talking .avatar{animation:profTalk .35s ease-in-out infinite alternate}.profe .bubble{transition:background .2s}.profe[data-mood=happy] .bubble{background:#ecffd9}.profe[data-mood=think] .bubble{background:#fff5d0}@keyframes profTalk{to{transform:translateY(-4px) rotate(2deg)}}@keyframes profJump{50%{transform:translateY(-12px) rotate(-3deg)}}@media(prefers-reduced-motion:reduce){.profe .avatar{animation:none!important;transform:none!important}}`;document.head.appendChild(profStyle);
function profTalk(text,force=false){profLast=text;const token=++profTicket;if(!('speechSynthesis'in window))return;speechSynthesis.cancel();if(!profVoice&&!force)return;const u=new SpeechSynthesisUtterance(clean(text).toLowerCase());u.lang='es-AR';u.rate=.76;const v=speechSynthesis.getVoices().find(v=>v.lang==='es-AR')||speechSynthesis.getVoices().find(v=>v.lang.startsWith('es'));if(v)u.voice=v;u.onstart=()=>{if(token===profTicket)document.querySelector('.profe')?.classList.add('talking')};u.onend=u.onerror=()=>{if(token===profTicket)document.querySelector('.profe')?.classList.remove('talking')};speechSynthesis.speak(u)}
function profSay(text,mood='guide',audio=true){const p=document.querySelector('.profe');if(!p)return;p.dataset.mood=mood;const bubble=p.querySelector('.bubble');bubble.innerHTML=text;profLast=text;bubble.setAttribute('aria-live','polite');let badge=p.querySelector('.prof-emotion');if(!badge){badge=document.createElement('span');badge.className='prof-emotion';badge.setAttribute('aria-hidden','true');p.appendChild(badge)}badge.textContent=({happy:'🌟',think:'🤔',guide:'💬'})[mood];const tools=document.createElement('div');tools.className='prof-tools';tools.innerHTML=`<button onclick="profHelp()">🙋 AYUDAME, PROFE</button><button onclick="profTalk(profLast,true)">🔊 REPETIR DESPACIO</button><button onclick="profToggle()">${profVoice?'🔊 VOZ ACTIVADA':'🔇 VOZ DESACTIVADA'}</button>`;bubble.appendChild(tools);const avatar=p.querySelector('.avatar');avatar.setAttribute('role','button');avatar.setAttribute('tabindex','0');avatar.setAttribute('aria-label','TOCÁ AL PROFE PARA PEDIR AYUDA');avatar.onclick=profHelp;avatar.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();profHelp()}};if(audio)profTalk(text)}
function profToggle(){profVoice=!profVoice;profSay(profLast,'guide',false);if(!profVoice&&'speechSynthesis'in window)speechSynthesis.cancel()}
function profHelp(){if(S.lab){const c=S.d.cells.filter(Boolean).length;profSay(`MIRÁ: EL ENTERO TIENE ${S.d.n} PARTES IGUALES. SEPARASTE ${c}. ARRIBA VA ${c} Y ABAJO VA ${S.d.n}. TOCÁ UNA PORCIÓN PARA CAMBIAR TU FRACCIÓN.`,'think');return}if(S.st<0){profSay('¡ACÁ ESTOY! ELEGÍ LA PRIMERA ESTACIÓN PARA APRENDER PASO A PASO. TAMBIÉN PODÉS ENTRAR AL LABORATORIO Y EXPERIMENTAR CONMIGO.');return}let text=STA[S.st].h;if(S.st===0){const c=S.d.cells?.filter(Boolean).length||0;text=`VAMOS JUNTOS. NECESITÁS ${S.d.k} PARTES Y SEPARASTE ${c}. `+(c<S.d.k?`FALTAN ${S.d.k-c}. TOCÁ OTRA PORCIÓN.`:c>S.d.k?`HAY ${c-S.d.k} DE MÁS. TOCÁ UNA PORCIÓN SEPARADA PARA DEVOLVERLA.`:'¡YA TENÉS LA CANTIDAD! TOCÁ ¡LISTO!')}if(S.st===4)text=`CONTÁ PRIMERO LAS PARTES SEPARADAS: ESE NÚMERO VA ARRIBA. DESPUÉS CONTÁ TODAS: ESE NÚMERO VA ABAJO. USÁ LOS BOTONES MÁS Y MENOS.`;profSay(text,'think')}
const profMap=renderMap;renderMap=function(){profMap();profSay('¡HOLA! SOY EL PROFE MARTÍN. AHORA JUGAMOS JUNTOS. PODÉS TOCARME PARA PEDIR AYUDA EN CUALQUIER MOMENTO.','guide',false)};
const profStation=startStation;startStation=function(i){profStation(i);profSay(STA[i].in.join('<br>'))};
const profChallenge=newChallenge;newChallenge=function(){profChallenge();profSay(Q[S.st]+(S.st===0?` NECESITÁS ${S.d.k} DE ${S.d.n} PARTES IGUALES.`:' VAMOS PASO A PASO. SI NECESITÁS AYUDA, TOCAME.'))};
const profTap=tapCell;tapCell=function(i){if(!S.lab&&S.ans)return;profTap(i);const c=S.d.cells.filter(Boolean).length;if(S.lab){let message=`¡BIEN! AHORA SEPARASTE ${c} DE ${S.d.n} PARTES. `;if(c===0)message+='JUNTASTE TODAS LAS PORCIONES OTRA VEZ.';else if(c===S.d.n)message+='¡TENÉS EL ENTERO COMPLETO!';else message+=`TU FRACCIÓN ES ${c} SOBRE ${S.d.n}.`;profSay(message,c===S.d.n?'happy':'guide')}else{profHelp()}};
const profHint=hint;hint=function(){profHint();profHelp()};
const profFin=fin;fin=function(ok,msg){if(S.ans)return;profFin(ok,msg);profSay(ok?`¡LO LOGRASTE! ${msg} `+(S.streak>=3?'¡YA LLEVÁS '+S.streak+' ACIERTOS SEGUIDOS!':'¡SEGUIMOS APRENDIENDO JUNTOS!'):`ESTÁ BIEN EQUIVOCARSE. ${msg} ${STA[S.st].h}`,ok?'happy':'think')};
const profLab=openLab;openLab=function(){profGoal=null;profLab();profSay('¡BIENVENIDO A MI LABORATORIO! TOCÁ UNA PORCIÓN PARA SEPARARLA. YO TE VOY CONTANDO QUÉ FRACCIÓN FORMÁS. TAMBIÉN PODÉS PEDIRME UN RETO.');profAddGoal()};
const profLabRender=renderLab;renderLab=function(){profLabRender();profAddGoal()};
function profAddGoal(){if(!S.lab||document.getElementById('profGoalButton'))return;const b=document.createElement('button');b.id='profGoalButton';b.className='btn';b.textContent='🎯 PROFE, DAME UN RETO';b.onclick=()=>{profGoal=1+Math.floor(Math.random()*(S.d.n-1));profSay(`MI RETO: SEPARÁ ${profGoal} DE ${S.d.n} PARTES IGUALES. CUANDO TERMINES, TOCÁ COMPROBAR RETO.`);const old=document.getElementById('profCheck');if(old)old.remove();const check=document.createElement('button');check.id='profCheck';check.className='btn';check.textContent='COMPROBAR RETO ✔';check.onclick=()=>{const c=S.d.cells.filter(Boolean).length;const ok=c===profGoal;profSay(ok?`¡RETO CUMPLIDO! SEPARASTE ${c} DE ${S.d.n}. ¡EXCELENTE TRABAJO!`:`TENÉS ${c} PARTES. TE PEDÍ ${profGoal}. `+(c<profGoal?`AGREGÁ ${profGoal-c} MÁS.`:`DEVOLVÉ ${c-profGoal}.`),ok?'happy':'think');if(ok)burst('⭐')};document.querySelector('.card')?.appendChild(check)};document.querySelector('.card')?.appendChild(b);if(profGoal&&S.lab){const target=document.createElement('p');target.className='big';target.textContent='RETO DEL PROFE: SEPARÁ '+profGoal+' DE '+S.d.n+' PARTES.';document.querySelector('.card')?.appendChild(target);const check=document.createElement('button');check.className='btn';check.textContent='COMPROBAR RETO ✔';check.id='profCheck';check.onclick=()=>{let c=S.d.cells.filter(Boolean).length;let ok=c===profGoal;profSay(ok?`¡BIEN HECHO! SEPARASTE ${c} DE ${S.d.n}. ¡RETO CUMPLIDO!`:`EL RETO ES SEPARAR ${profGoal} PARTES. TENÉS ${c}. `+(c<profGoal?`FALTAN ${profGoal-c}.`:`DEVOLVÉ ${c-profGoal}.`),ok?'happy':'think');if(ok)burst('⭐')};document.querySelector('.card')?.appendChild(check)}}
const profParts=labParts;labParts=function(n){profGoal=null;profParts(n);profSay(`AHORA DIVIDIMOS EL ENTERO EN ${n} PARTES IGUALES. CADA UNA REPRESENTA UNO SOBRE ${n}. ¡PROBÁ SEPARARLAS!`)};
const profFood=setFood;setFood=function(k){profFood(k);profSay(`¡AHORA JUGAMOS CON ${k==='pizza'?'PIZZA':'CHOCOLATE'}! LAS PARTES SIGUEN SIENDO IGUALES. TOCÁ LAS PORCIONES QUE QUIERAS SEPARAR.`)};
renderMap();

const profRenderChallenge=renderChallenge;renderChallenge=function(){profRenderChallenge();profSay(Q[S.st],'guide',false)};
